/**
 * Generate the test fixture's sample media under tests/fixtures/offline/media/
 * ===========================================================================
 * The tests load no media from the internet. When the site asks for a remote
 * sample photo, avatar, placeholder, audio clip or video, the offline fixture
 * (tests/fixtures/offline.ts) answers with one of the stand-ins GENERATED by
 * this script -- nothing here is downloaded, so there is no third-party
 * licence to track (see tests/fixtures/offline/media/MEDIA.md).
 *
 * Deterministic: a fixed seed per asset, so re-running produces the same
 * scenes. (Byte-identical output is not promised across sharp/libvpx/LAME
 * versions.)
 *
 * Tools:
 *   - images: sharp (devDependency) rasterises procedurally drawn SVG scenes;
 *   - video:  frames rendered with sharp, encoded to VP8/WebM by the ffmpeg
 *             build Playwright downloads (`npx playwright install ffmpeg`);
 *   - audio:  PCM synthesised here, encoded to MP3 by python3 + `lameenc`
 *             (`pip install lameenc`). Only the encoder is borrowed; the
 *             sound is ours.
 *
 * Usage:
 *   node scripts/generate-sample-media.mjs [--only=photos,avatars,placeholders,audio,video]
 *
 * The remote URL -> stand-in mapping is localFor() in
 * scripts/sample-media-catalog.mjs.
 */

import { mkdirSync, writeFileSync, readdirSync, existsSync, statSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { spawnSync, spawn } from 'child_process';
import { homedir } from 'os';
import { Buffer } from 'buffer';
import sharp from 'sharp';
import { PHOTOS, AVATARS, PLACEHOLDERS, AUDIO, VIDEO } from './sample-media-catalog.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = join(ROOT, 'tests', 'fixtures', 'offline', 'media');
const only = (process.argv.find((a) => a.startsWith('--only=')) || '').slice(7).split(',').filter(Boolean);
const want = (kind) => only.length === 0 || only.includes(kind);

// ── deterministic randomness ────────────────────────────────────────────────
function rngFor(seed) {
  let h = 2166136261;
  for (const ch of String(seed)) h = Math.imul(h ^ ch.charCodeAt(0), 16777619);
  let a = h >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const lerp = (a, b, t) => a + (b - a) * t;
const hex = (c) => '#' + c.map((v) => Math.round(Math.max(0, Math.min(255, v))).toString(16).padStart(2, '0')).join('');
const parse = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
const mix = (a, b, t) => hex(parse(a).map((v, i) => lerp(v, parse(b)[i], t)));

// ── scene painters: each returns SVG body markup for a W x H canvas ─────────
function ridge(W, H, r, base, rough, steps = 48) {
  const pts = [];
  let y = base;
  for (let i = 0; i <= steps; i++) {
    const x = (i / steps) * W;
    y += (r() - 0.5) * rough;
    y = Math.max(H * 0.15, Math.min(H * 0.95, y + (base - y) * 0.08));
    pts.push(`${x.toFixed(1)},${y.toFixed(1)}`);
  }
  return `M0,${H} L${pts.join(' L')} L${W},${H} Z`;
}

function sky(id, stops) {
  return `<linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1">${stops
    .map(([o, c]) => `<stop offset="${o}" stop-color="${c}"/>`)
    .join('')}</linearGradient>`;
}

function grain(W, H, seed, opacity = 0.07) {
  return {
    defs: `<filter id="grain" x="0" y="0" width="100%" height="100%"><feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="2" seed="${seed}"/><feColorMatrix type="saturate" values="0"/></filter>`,
    body: `<rect width="${W}" height="${H}" filter="url(#grain)" opacity="${opacity}"/>`,
  };
}

const SCENES = {
  mountains(W, H, r, p) {
    const g = grain(W, H, Math.floor(r() * 999));
    const sunX = W * (0.2 + r() * 0.6), sunY = H * (0.25 + r() * 0.15);
    let layers = '';
    const n = 5;
    for (let i = 0; i < n; i++) {
      const t = i / (n - 1);
      layers += `<path d="${ridge(W, H, r, H * lerp(0.42, 0.8, t), H * lerp(0.14, 0.06, t))}" fill="${mix(p.far, p.near, t)}"/>`;
    }
    return `<defs>${sky('s', [[0, p.top], [0.6, p.mid], [1, p.low]])}<radialGradient id="sun"><stop offset="0" stop-color="${p.sun}"/><stop offset="0.25" stop-color="${p.sun}" stop-opacity="0.9"/><stop offset="1" stop-color="${p.sun}" stop-opacity="0"/></radialGradient>${g.defs}</defs>
<rect width="${W}" height="${H}" fill="url(#s)"/><circle cx="${sunX}" cy="${sunY}" r="${H * 0.35}" fill="url(#sun)"/>${layers}${g.body}`;
  },
  lake(W, H, r, p) {
    const g = grain(W, H, Math.floor(r() * 999));
    const horizon = H * 0.58;
    let hills = '';
    for (let i = 0; i < 3; i++) hills += `<path d="${ridge(W, horizon, r, horizon * lerp(0.55, 0.85, i / 2), horizon * 0.12)}" fill="${mix(p.far, p.near, i / 2)}"/>`;
    return `<defs>${sky('s', [[0, p.top], [0.7, p.mid], [1, p.low]])}${sky('w', [[0, p.low], [1, p.water]])}${g.defs}</defs>
<rect width="${W}" height="${H}" fill="url(#s)"/><circle cx="${W * 0.62}" cy="${horizon * 0.62}" r="${H * 0.06}" fill="${p.sun}"/>
<g>${hills}</g><rect y="${horizon}" width="${W}" height="${H - horizon}" fill="url(#w)"/>
<g transform="translate(0 ${horizon * 2}) scale(1 -1)" opacity="0.35">${hills}</g>
${Array.from({ length: 14 }, () => `<rect x="${r() * W}" y="${lerp(horizon, H, r())}" width="${W * (0.05 + r() * 0.2)}" height="1.5" fill="#ffffff" opacity="${0.15 + r() * 0.25}"/>`).join('')}${g.body}`;
  },
  ocean(W, H, r, p) {
    const g = grain(W, H, Math.floor(r() * 999));
    const horizon = H * (0.45 + r() * 0.1);
    let waves = '';
    for (let i = 0; i < 18; i++) {
      const y = lerp(horizon + 6, H, (i / 18) ** 1.4);
      const amp = lerp(1.5, 10, i / 18), len = lerp(60, 260, i / 18), ph = r() * len;
      let d = `M0,${y}`;
      for (let x = 0; x <= W + len; x += len / 2) d += ` Q${x - ph + len / 4},${y - amp} ${x - ph + len / 2},${y}`;
      waves += `<path d="${d}" fill="none" stroke="#ffffff" stroke-opacity="${lerp(0.08, 0.28, i / 18)}" stroke-width="${lerp(1, 3, i / 18)}"/>`;
    }
    return `<defs>${sky('s', [[0, p.top], [1, p.low]])}${sky('w', [[0, p.water], [1, p.near]])}<radialGradient id="glow"><stop offset="0" stop-color="${p.sun}" stop-opacity="0.9"/><stop offset="1" stop-color="${p.sun}" stop-opacity="0"/></radialGradient>${g.defs}</defs>
<rect width="${W}" height="${H}" fill="url(#s)"/><circle cx="${W * 0.5}" cy="${horizon}" r="${H * 0.3}" fill="url(#glow)"/>
<rect y="${horizon}" width="${W}" height="${H - horizon}" fill="url(#w)"/><rect x="${W * 0.47}" y="${horizon}" width="${W * 0.06}" height="${H - horizon}" fill="${p.sun}" opacity="0.18"/>${waves}${g.body}`;
  },
  city(W, H, r, p) {
    const g = grain(W, H, Math.floor(r() * 999), 0.05);
    const ground = H * 0.82;
    let b = '', lit = '';
    for (let layer = 0; layer < 2; layer++) {
      let x = -10;
      while (x < W) {
        const bw = W * (0.04 + r() * 0.07), bh = H * (layer ? 0.2 + r() * 0.45 : 0.3 + r() * 0.35);
        const col = layer ? p.near : p.far;
        b += `<rect x="${x.toFixed(1)}" y="${(ground - bh).toFixed(1)}" width="${bw.toFixed(1)}" height="${bh.toFixed(1)}" fill="${col}"/>`;
        if (layer) {
          for (let wy = ground - bh + 8; wy < ground - 8; wy += 12) {
            for (let wx = x + 5; wx < x + bw - 6; wx += 9) if (r() < 0.32) lit += `<rect x="${wx.toFixed(1)}" y="${wy.toFixed(1)}" width="4" height="6" fill="${p.sun}" opacity="${(0.5 + r() * 0.5).toFixed(2)}"/>`;
          }
        }
        x += bw + (layer ? r() * 6 : r() * 2);
      }
    }
    return `<defs>${sky('s', [[0, p.top], [0.65, p.mid], [1, p.low]])}${sky('rf', [[0, p.near], [1, p.water]])}${g.defs}</defs>
<rect width="${W}" height="${H}" fill="url(#s)"/>${b}${lit}<rect y="${ground}" width="${W}" height="${H - ground}" fill="url(#rf)"/>
<g transform="translate(0 ${ground * 2}) scale(1 -1)" opacity="0.22">${lit}</g>${g.body}`;
  },
  forest(W, H, r, p) {
    const g = grain(W, H, Math.floor(r() * 999));
    let trees = '';
    for (let layer = 0; layer < 4; layer++) {
      const t = layer / 3, base = H * lerp(0.62, 1.02, t), size = H * lerp(0.12, 0.34, t);
      const col = mix(p.far, p.near, t);
      trees += `<rect y="${base - size * 0.1}" width="${W}" height="${H}" fill="${col}"/>`;
      for (let x = -20; x < W + 20; x += size * (0.25 + r() * 0.25)) {
        const h = size * (0.7 + r() * 0.6), w = h * 0.34;
        trees += `<path d="M${x.toFixed(1)},${(base - h).toFixed(1)} L${(x + w / 2).toFixed(1)},${base} L${(x - w / 2).toFixed(1)},${base} Z" fill="${col}"/>`;
      }
      trees += `<rect width="${W}" height="${H}" fill="${p.mid}" opacity="${lerp(0.18, 0, t)}"/>`;
    }
    return `<defs>${sky('s', [[0, p.top], [1, p.low]])}${g.defs}</defs><rect width="${W}" height="${H}" fill="url(#s)"/>${trees}${g.body}`;
  },
  dunes(W, H, r, p) {
    const g = grain(W, H, Math.floor(r() * 999), 0.09);
    let d = '';
    for (let i = 0; i < 5; i++) {
      const t = i / 4, y0 = H * lerp(0.5, 0.85, t);
      const c1 = [W * r(), y0 - H * (0.08 + r() * 0.1)], c2 = [W * r(), y0 + H * 0.05 * (r() - 0.5)];
      d += `<path d="M0,${y0} C${c1[0]},${c1[1]} ${c2[0]},${c2[1]} ${W},${y0 - H * 0.04 * (r() - 0.5)} L${W},${H} L0,${H} Z" fill="${mix(p.far, p.near, t)}"/>`;
      d += `<path d="M0,${y0} C${c1[0]},${c1[1]} ${c2[0]},${c2[1]} ${W},${y0}" fill="none" stroke="#ffffff" stroke-opacity="0.18" stroke-width="2"/>`;
    }
    return `<defs>${sky('s', [[0, p.top], [1, p.low]])}${g.defs}</defs><rect width="${W}" height="${H}" fill="url(#s)"/><circle cx="${W * 0.78}" cy="${H * 0.22}" r="${H * 0.07}" fill="${p.sun}"/>${d}${g.body}`;
  },
  aurora(W, H, r, p) {
    const g = grain(W, H, Math.floor(r() * 999), 0.05);
    let stars = '';
    for (let i = 0; i < Math.round(W * H / 2600); i++) stars += `<circle cx="${(r() * W).toFixed(1)}" cy="${(r() * H * 0.75).toFixed(1)}" r="${(0.4 + r() * 1.2).toFixed(2)}" fill="#fff" opacity="${(0.3 + r() * 0.7).toFixed(2)}"/>`;
    let bands = '';
    for (let i = 0; i < 3; i++) {
      const y = H * (0.2 + i * 0.1 + r() * 0.05);
      bands += `<path d="M${-W * 0.1},${y + H * 0.1} C${W * 0.3},${y - H * 0.15} ${W * 0.6},${y + H * 0.2} ${W * 1.1},${y - H * 0.05}" fill="none" stroke="${i % 2 ? p.sun : p.mid}" stroke-width="${H * 0.08}" stroke-opacity="0.35" filter="url(#blur)"/>`;
    }
    return `<defs>${sky('s', [[0, p.top], [1, p.low]])}<filter id="blur"><feGaussianBlur stdDeviation="${H * 0.03}"/></filter>${g.defs}</defs>
<rect width="${W}" height="${H}" fill="url(#s)"/>${stars}${bands}<path d="${ridge(W, H, r, H * 0.8, H * 0.08)}" fill="${p.near}"/>${g.body}`;
  },
  hills(W, H, r, p) {
    const g = grain(W, H, Math.floor(r() * 999), 0.05);
    let clouds = '';
    for (let i = 0; i < 5; i++) {
      const cx = r() * W, cy = H * (0.1 + r() * 0.25), s = H * (0.05 + r() * 0.05);
      clouds += `<g fill="#fff" opacity="0.85" filter="url(#soft)"><ellipse cx="${cx}" cy="${cy}" rx="${s * 2.2}" ry="${s}"/><ellipse cx="${cx + s}" cy="${cy - s * 0.5}" rx="${s * 1.3}" ry="${s * 0.9}"/></g>`;
    }
    let h = '';
    for (let i = 0; i < 4; i++) {
      const t = i / 3, y = H * lerp(0.55, 0.85, t);
      h += `<path d="M0,${y} C${W * 0.25},${y - H * (0.1 + r() * 0.1)} ${W * 0.6},${y + H * 0.08} ${W},${y - H * 0.06 * r()} L${W},${H} L0,${H} Z" fill="${mix(p.far, p.near, t)}"/>`;
    }
    return `<defs>${sky('s', [[0, p.top], [1, p.low]])}<filter id="soft"><feGaussianBlur stdDeviation="${H * 0.01}"/></filter>${g.defs}</defs><rect width="${W}" height="${H}" fill="url(#s)"/>${clouds}${h}${g.body}`;
  },
  bokeh(W, H, r, p) {
    let c = '';
    for (let i = 0; i < 40; i++) {
      const rad = Math.min(W, H) * (0.03 + r() * 0.12);
      c += `<circle cx="${(r() * W).toFixed(1)}" cy="${(r() * H).toFixed(1)}" r="${rad.toFixed(1)}" fill="${[p.sun, p.mid, p.low, '#ffffff'][i % 4]}" opacity="${(0.12 + r() * 0.35).toFixed(2)}"/>`;
    }
    return `<defs>${sky('s', [[0, p.top], [1, p.near]])}<filter id="b"><feGaussianBlur stdDeviation="${Math.min(W, H) * 0.012}"/></filter></defs><rect width="${W}" height="${H}" fill="url(#s)"/><g filter="url(#b)">${c}</g>`;
  },
};

const PALETTES = {
  dawn: { top: '#2b3a67', mid: '#e38b6d', low: '#f7c59f', sun: '#fff1d0', far: '#8d7fa6', near: '#2c2440', water: '#3b4d7a' },
  alpine: { top: '#5b8fd6', mid: '#a9cbef', low: '#e6f0fa', sun: '#ffffff', far: '#9fb5c9', near: '#2f4858', water: '#4a7ba6' },
  sunset: { top: '#1e2a5a', mid: '#f25f5c', low: '#ffb563', sun: '#ffe066', far: '#7b4b73', near: '#1b1b2f', water: '#2d3561' },
  dusk: { top: '#0f1c3f', mid: '#4b3f72', low: '#f08a5d', sun: '#ffd166', far: '#2c3e63', near: '#141a2e', water: '#0b1022' },
  mist: { top: '#c9d6df', mid: '#dfe7ec', low: '#f2f5f7', sun: '#ffffff', far: '#9fb3a8', near: '#1f3b2c', water: '#6b8f8a' },
  desert: { top: '#79b4d9', mid: '#f3d9a4', low: '#f7e3bd', sun: '#fff8e1', far: '#e8b77a', near: '#b86b3c', water: '#d9a066' },
  night: { top: '#050814', mid: '#2ee6a8', low: '#10224a', sun: '#8a5cf6', far: '#0b1530', near: '#03060f', water: '#0b1530' },
  meadow: { top: '#4f9de8', mid: '#9fd0f5', low: '#dff1fb', sun: '#ffffff', far: '#8fc07a', near: '#2f6b35', water: '#3f8f6b' },
  ocean: { top: '#3d7cc9', mid: '#a4d3f5', low: '#d9eefc', sun: '#ffffff', far: '#5c9bd1', near: '#0c3b66', water: '#2f78b5' },
  warm: { top: '#3a1c71', mid: '#d76d77', low: '#ffaf7b', sun: '#fff3b0', far: '#6a3d7a', near: '#1d0f33', water: '#4a2c6b' },
  teal: { top: '#0f3443', mid: '#34e89e', low: '#9be7c4', sun: '#e0fff4', far: '#1d5a63', near: '#082129', water: '#0f3443' },
};

async function writePhoto({ file, w, h, scene, palette, seed }) {
  const r = rngFor(seed);
  const body = SCENES[scene](w, h, r, PALETTES[palette]);
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">${body}</svg>`;
  const out = join(OUT, file);
  mkdirSync(dirname(out), { recursive: true });
  await sharp(Buffer.from(svg)).jpeg({ quality: 70, mozjpeg: true, progressive: true }).toFile(out);
}

// ── avatars: generated illustrated portraits (no real person) ───────────────
const SKIN = ['#f1c27d', '#e0ac69', '#c68642', '#8d5524', '#ffdbac', '#d4a373'];
const HAIR = ['#2b1b17', '#5a3825', '#a55728', '#d6b370', '#1c1c1c', '#8e8e8e'];
const BG = ['#6366f1', '#0ea5e9', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#14b8a6', '#ec4899'];
async function writeAvatar({ file, seed, index }) {
  const r = rngFor(seed);
  const S = 256, skin = SKIN[index % SKIN.length], hair = HAIR[(index * 5 + 1) % HAIR.length];
  const bg = BG[index % BG.length], shirt = mix(BG[(index + 3) % BG.length], '#1f2937', 0.35);
  const long = index % 2 === 1;
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${S}" height="${S}" viewBox="0 0 ${S} ${S}">
<defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${mix(bg, '#ffffff', 0.25)}"/><stop offset="1" stop-color="${bg}"/></linearGradient></defs>
<rect width="${S}" height="${S}" fill="url(#bg)"/>
${long ? `<path d="M68,120 Q60,210 88,236 L168,236 Q196,210 188,120 Z" fill="${hair}"/>` : ''}
<path d="M40,${S} Q44,196 128,188 Q212,196 216,${S} Z" fill="${shirt}"/>
<rect x="110" y="150" width="36" height="44" rx="12" fill="${mix(skin, '#000000', 0.08)}"/>
<ellipse cx="128" cy="118" rx="52" ry="${60 + r() * 4}" fill="${skin}"/>
<path d="M74,112 Q${72 + r() * 10},${50 + r() * 10} 128,54 Q${178 + r() * 8},${52 + r() * 8} 182,112 Q${170 - r() * 20},${76 + r() * 10} 128,78 Q${92 + r() * 10},80 74,112 Z" fill="${hair}"/>
<ellipse cx="108" cy="122" rx="5" ry="6" fill="#1f2937"/><ellipse cx="148" cy="122" rx="5" ry="6" fill="#1f2937"/>
<path d="M112,${148 + r() * 3} Q128,${158 + r() * 4} 144,${148 + r() * 3}" fill="none" stroke="#7c2d12" stroke-width="4" stroke-linecap="round"/>
</svg>`;
  const out = join(OUT, file);
  mkdirSync(dirname(out), { recursive: true });
  await sharp(Buffer.from(svg)).jpeg({ quality: 80, mozjpeg: true }).toFile(out);
}

// ── placeholders: SVG, drawn by the browser, text preserved ─────────────────
function writePlaceholder({ file, w, h, bg, fg, text }) {
  const size = Math.max(10, Math.min(w / Math.max(4, text.length * 0.62), h * 0.3));
  const esc = text.replace(/&/g, '&amp;').replace(/</g, '&lt;');
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc}">
<!-- Generated by scripts/generate-sample-media.mjs; see tests/fixtures/offline/media/MEDIA.md -->
<rect width="${w}" height="${h}" fill="#${bg}"/>
<text x="50%" y="50%" dominant-baseline="central" text-anchor="middle" fill="#${fg}" font-family="system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif" font-size="${size.toFixed(1)}" font-weight="600">${esc}</text>
</svg>
`;
  const out = join(OUT, file);
  mkdirSync(dirname(out), { recursive: true });
  writeFileSync(out, svg);
}

// ── audio: additive synthesis -> 16-bit PCM -> MP3 (lameenc) ────────────────
const RATE = 44100;
const midi = (n) => 440 * 2 ** ((n - 69) / 12);

function synth({ seconds, tempo, chords, style, seed }) {
  const r = rngFor(seed);
  const N = Math.round(seconds * RATE);
  const L = new Float32Array(N), R = new Float32Array(N);
  const beat = 60 / tempo;
  const add = (buf, start, dur, freq, amp, { attack = 0.01, release = 0.3, harmonics = [1], detune = 0 } = {}) => {
    const s0 = Math.floor(start * RATE), n = Math.floor((dur + release) * RATE);
    for (let i = 0; i < n && s0 + i < N; i++) {
      const t = i / RATE;
      let env = t < attack ? t / attack : t < dur ? 1 : Math.max(0, 1 - (t - dur) / release);
      env *= env;
      let v = 0;
      harmonics.forEach((h, k) => { v += (h * Math.sin(2 * Math.PI * freq * (k + 1) * (1 + detune) * t)); });
      buf[s0 + i] += v * amp * env;
    }
  };
  const bar = beat * 4;
  const bars = Math.ceil(seconds / bar);
  for (let b = 0; b < bars; b++) {
    const chord = chords[b % chords.length];
    const t0 = b * bar;
    if (style === 'pad' || style === 'bells') {
      chord.forEach((n) => {
        add(L, t0, bar * 0.95, midi(n), 0.07, { attack: bar * 0.35, release: bar * 0.6, harmonics: [1, 0.35, 0.12], detune: 0.0015 });
        add(R, t0, bar * 0.95, midi(n), 0.07, { attack: bar * 0.35, release: bar * 0.6, harmonics: [1, 0.35, 0.12], detune: -0.0015 });
      });
      add(L, t0, bar, midi(chord[0] - 12), 0.09, { attack: 0.4, release: 1.2, harmonics: [1, 0.2] });
      add(R, t0, bar, midi(chord[0] - 12), 0.09, { attack: 0.4, release: 1.2, harmonics: [1, 0.2] });
    }
    if (style === 'bells') {
      for (let k = 0; k < 4; k++) {
        if (r() < 0.75) {
          const n = chord[Math.floor(r() * chord.length)] + 12;
          const buf = r() < 0.5 ? L : R;
          add(buf, t0 + k * beat + (r() < 0.3 ? beat / 2 : 0), 0.05, midi(n), 0.08, { attack: 0.002, release: 1.8, harmonics: [1, 0.5, 0.25, 0.1] });
        }
      }
    }
    if (style === 'arp' || style === 'pulse') {
      const steps = style === 'arp' ? 8 : 4;
      for (let k = 0; k < steps * 2; k++) {
        const n = chord[k % chord.length] + (style === 'arp' ? 12 * (Math.floor(k / chord.length) % 2) : 0);
        const st = t0 + (k * bar) / (steps * 2);
        const pan = (k % 2) ? 0.7 : 1;
        add(L, st, bar / (steps * 2) * 0.6, midi(n), 0.07 * pan, { attack: 0.004, release: 0.25, harmonics: [1, 0.45, 0.2, 0.1] });
        add(R, st, bar / (steps * 2) * 0.6, midi(n), 0.07 * (1.7 - pan), { attack: 0.004, release: 0.25, harmonics: [1, 0.45, 0.2, 0.1] });
      }
      add(L, t0, bar * 0.9, midi(chord[0] - 12), 0.1, { attack: 0.02, release: 0.4, harmonics: [1, 0.3] });
      add(R, t0, bar * 0.9, midi(chord[0] - 12), 0.1, { attack: 0.02, release: 0.4, harmonics: [1, 0.3] });
      if (style === 'pulse') {
        for (let k = 0; k < 4; k++) {
          // soft kick: a falling sine
          const s0 = Math.floor((t0 + k * beat) * RATE);
          for (let i = 0; i < RATE * 0.25 && s0 + i < N; i++) {
            const t = i / RATE, v = Math.sin(2 * Math.PI * (50 + 90 * Math.exp(-t * 30)) * t) * Math.exp(-t * 14) * 0.35;
            L[s0 + i] += v; R[s0 + i] += v;
          }
        }
      }
    }
    if (style === 'chime') {
      chord.forEach((n, i) => { add(L, i * 0.12, 0.05, midi(n + 12), 0.14, { attack: 0.002, release: 2.2, harmonics: [1, 0.4, 0.2] }); add(R, i * 0.12 + 0.01, 0.05, midi(n + 12), 0.14, { attack: 0.002, release: 2.2, harmonics: [1, 0.4, 0.2] }); });
    }
  }
  // simple feedback echo for space, then fade in/out and normalise
  const d = Math.floor(RATE * beat * 0.75);
  for (let i = d; i < N; i++) { L[i] += R[i - d] * 0.28; R[i] += L[i - d] * 0.28; }
  const fade = Math.min(RATE * 1.5, N / 4);
  let peak = 0;
  for (let i = 0; i < N; i++) {
    const f = Math.min(1, i / (RATE * 0.05), (N - i) / fade);
    L[i] *= f; R[i] *= f;
    peak = Math.max(peak, Math.abs(L[i]), Math.abs(R[i]));
  }
  const pcm = Buffer.alloc(N * 4);
  const g = 0.89 / (peak || 1);
  for (let i = 0; i < N; i++) {
    pcm.writeInt16LE(Math.round(Math.tanh(L[i] * g) * 32767), i * 4);
    pcm.writeInt16LE(Math.round(Math.tanh(R[i] * g) * 32767), i * 4 + 2);
  }
  return pcm;
}

function encodeMp3(pcm, out, kbps) {
  const py = `
import sys, lameenc
enc = lameenc.Encoder()
enc.set_bit_rate(${kbps}); enc.set_in_sample_rate(${RATE}); enc.set_channels(2); enc.set_quality(2)
data = sys.stdin.buffer.read()
open(sys.argv[1], 'wb').write(enc.encode(data) + enc.flush())
`;
  const py3 = process.env.PYTHON || 'python3';
  const res = spawnSync(py3, ['-c', py, out], { input: pcm, maxBuffer: 1 << 30 });
  if (res.status !== 0) {
    throw new Error(`MP3 encode failed (${py3} needs the lameenc package: pip install lameenc):\n${res.stderr}`);
  }
}

// ── video: frames from sharp -> VP8/WebM via Playwright's ffmpeg ────────────
function findFfmpeg() {
  if (process.env.FFMPEG) return process.env.FFMPEG;
  const roots = [process.env.PLAYWRIGHT_BROWSERS_PATH, join(homedir(), '.cache', 'ms-playwright')].filter(Boolean);
  for (const root of roots) {
    if (!existsSync(root)) continue;
    for (const d of readdirSync(root).filter((n) => n.startsWith('ffmpeg')).sort().reverse()) {
      const bin = join(root, d, process.platform === 'win32' ? 'ffmpeg-win64.exe' : process.platform === 'darwin' ? 'ffmpeg-mac' : 'ffmpeg-linux');
      if (existsSync(bin)) return bin;
    }
  }
  throw new Error('No ffmpeg found. Run `npx playwright install ffmpeg` or set FFMPEG=/path/to/ffmpeg.');
}

async function writeVideo({ file, poster, w, h, seconds, fps, scene, palette, seed }) {
  const out = join(OUT, file);
  mkdirSync(dirname(out), { recursive: true });
  const ff = spawn(findFfmpeg(), ['-y', '-loglevel', 'error', '-f', 'image2pipe', '-framerate', String(fps), '-c:v', 'mjpeg', '-i', 'pipe:0',
    '-c:v', 'libvpx', '-b:v', '600k', '-crf', '12', '-deadline', 'good', '-cpu-used', '2', '-auto-alt-ref', '0', '-pix_fmt', 'yuv420p', '-an', out], { stdio: ['pipe', 'inherit', 'inherit'] });
  const done = new Promise((res, rej) => ff.on('close', (c) => (c === 0 ? res() : rej(new Error(`ffmpeg exited ${c}`)))));
  const total = seconds * fps;
  const p = PALETTES[palette];
  // A static scene rendered once at 2x width; the camera pans across it while
  // a sun/moon glow drifts, so the clip visibly moves.
  const wide = SCENES[scene](w * 2, h, rngFor(seed), p);
  const baseSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="${w * 2}" height="${h}">${wide}</svg>`;
  const base = await sharp(Buffer.from(baseSvg)).png().toBuffer();
  for (let f = 0; f < total; f++) {
    const t = f / total;
    const ease = 0.5 - 0.5 * Math.cos(Math.PI * 2 * t); // ping-pong so the clip loops seamlessly
    const left = Math.round(ease * w);
    const gx = w * (0.2 + 0.6 * t), gy = h * (0.3 + 0.1 * Math.sin(t * Math.PI * 2));
    const glow = Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}"><defs><radialGradient id="g"><stop offset="0" stop-color="${p.sun}" stop-opacity="0.55"/><stop offset="1" stop-color="${p.sun}" stop-opacity="0"/></radialGradient></defs><circle cx="${gx}" cy="${gy}" r="${h * 0.3}" fill="url(#g)"/></svg>`);
    const frame = await sharp(base).extract({ left, top: 0, width: w, height: h }).composite([{ input: glow }]).jpeg({ quality: 90 }).toBuffer();
    if (!ff.stdin.write(frame)) await new Promise((res) => ff.stdin.once('drain', res));
    if (poster && f === 0) await sharp(frame).jpeg({ quality: 75, mozjpeg: true }).toFile(join(OUT, poster));
  }
  ff.stdin.end();
  await done;
}

// ── main ─────────────────────────────────────────────────────────────────────
const t0 = Date.now();
if (want('photos')) for (const p of PHOTOS) await writePhoto(p);
if (want('avatars')) for (const a of AVATARS) await writeAvatar(a);
if (want('placeholders')) for (const p of PLACEHOLDERS) writePlaceholder(p);
if (want('audio')) {
  for (const a of AUDIO) {
    const out = join(OUT, a.file);
    mkdirSync(dirname(out), { recursive: true });
    encodeMp3(synth(a), out, a.kbps);
  }
}
if (want('video')) for (const v of VIDEO) await writeVideo(v);

let bytes = 0, files = 0;
const walk = (d) => { for (const n of readdirSync(d)) { const f = join(d, n); if (statSync(f).isDirectory()) walk(f); else { bytes += statSync(f).size; files++; } } };
walk(OUT);
console.log(`tests/fixtures/offline/media: ${files} files, ${(bytes / 1024 / 1024).toFixed(2)} MB (${((Date.now() - t0) / 1000).toFixed(1)}s)`);
